# Builds tiny synthetic .gcode fixtures for the suite - real exported files are MBs, these are KBs
# and let us control the "filament used" line exactly, including a zero-usage case.
import os
HERE = os.path.dirname(os.path.abspath(__file__))

def write(name, tail_usage_line):
    path = os.path.join(HERE, name)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write("; HEADER_BLOCK_START\n")
        fh.write("; generated by OrcaSlicer 2.5.2 on 2026-11-24 at 17:25:55\n")
        fh.write("; total layer number: 10\n")
        fh.write("; filament_density: 1.26,1.26,1.26,1.26\n")
        fh.write("; filament_diameter: 1.75,1.75,1.75,1.75\n")
        fh.write("; filament: 2,3,4,1\n")
        fh.write("; HEADER_BLOCK_END\n")
        fh.write("G28\n" * 50)   # padding so the usage line is genuinely near the END, not the start
        fh.write("T0\nG1 X10 E1\nT1\nG1 X20 E1\n")
        if tail_usage_line is not None:
            fh.write("; filament used [mm] = " + tail_usage_line + "\n")
            fh.write("; total filament used [g] = 9.9\n")
    return path

write("two_of_four_used.gcode", "120.5, 85.2, 0.00, 0.00")     # T0+T1 used, T2/T3 not - the user's reported case
write("all_four_used.gcode", "100.0, 50.0, 25.0, 10.0")        # every slot used - nothing should be hidden
write("no_usage_line.gcode", None)                              # header has no stats at all - must fail open (show everything)
print("fixtures written in", HERE)
